def intersection(interval1, interval2):
    def length_of_intersection(interval1, interval2):
        start = max(interval1[0], interval2[0])
        end = min(interval1[1], interval2[1])
        return max(0, end - start)  # Length cannot be negative

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    intersect_length = length_of_intersection(interval1, interval2)

    if intersect_length > 0 and is_prime(intersect_length):
        return "YES"
    else:
        return "NO"

